(* [comment removed for export] *)
Lemma inregsV_kept R1 R2 sp ov sv ec sh8 (KS : list nat) :
  inregsV R1 sp ov sv ec sh8 -> (forall x, In x KS -> getr R2 (reg x) = getr R1 (reg x)) ->
