Lemma pl_call (UVt : utf8_valid l = true) (fxq : FPState) Rq Mq mdq LKq Awq crq kq :
  INV Mq mdq LKq Awq crq kq 1 ->
  getr Rq (reg 1) = Z_to_bv 64 0xad9a4 -> getr Rq (reg 2) = Z_to_bv 64 (sp - 96) -> getr Rq (reg 10) = Z_to_bv 64 (PMSPA.o_v AD fb) -> getr Rq (reg 11) = Z_to_bv 64 n -> csk Rq ->
  (forall (fx2 : FPState) R2 M2 md2 LK2 Aw2 cr2 k2, INV M2 md2 LK2 Aw2 cr2 k2 (1 + pl_size n) -> regs_preserved Rq R2 ->
      srealizes RSEGS SCFG (PMSPA.cfg RSEGS (fx:=fx2) R2 0xad9a4 M2 md2) K) ->
  srealizes RSEGS SCFG (PMSPA.cfg RSEGS (fx:=fxq) Rq 0xafe84 Mq mdq) K.
Proof.
