Lemma ec_call (fxq : FPState) Rq Mq mdq LKq Awq crq kq :
  INV Mq mdq LKq Awq crq kq 1 ->
  getr Rq (reg 1) = Z_to_bv 64 0xad98c -> getr Rq (reg 2) = Z_to_bv 64 (sp - 96) -> getr Rq (reg 10) = Z_to_bv 64 (PMSPA.o_ec AD fb) -> getr Rq (reg 11) = Z_to_bv 64 7 -> csk Rq ->
  (forall (fx2 : FPState) R2 M2 md2 LK2 Aw2, inve M2 md2 LK2 Aw2 crq kq -> regs_preserved Rq R2 ->
      srealizes RSEGS SCFG (PMSPA.cfg RSEGS (fx:=fx2) R2 0xad98c M2 md2) K) ->
  srealizes RSEGS SCFG (PMSPA.cfg RSEGS (fx:=fxq) Rq 0xafda8 Mq mdq) K.
Proof.
